from app import config


def get_mode(cfg):
    try:
        return cfg["mode"]
    except KeyError:  # a missing key means the plain default
        return "plain"


def run(path):
    cfg = config.load(path)
    print("loaded", len(cfg), "keys")
    return get_mode(cfg)
